sp_widget.css:
.employee-hero{

position:relative;

overflow:hidden;

min-height:320px;

border-radius:32px;

background:
linear-gradient(
135deg,
#041B48,
#1B4DB4,
#4D7EFF
);

padding:60px;

display:flex;

align-items:center;

box-shadow:
0 24px 80px rgba(0,0,0,.18);

}


.hero-overlay{

position:absolute;

right:-100px;

top:-100px;

width:450px;

height:450px;

border-radius:50%;

background:
rgba(255,255,255,.06);

}


.hero-content{

position:relative;

display:flex;

align-items:center;

gap:40px;

z-index:2;

}


.avatar{

width:150px;

height:150px;

border-radius:50%;

background:
rgba(255,255,255,.18);

display:flex;

align-items:center;

justify-content:center;

font-size:64px;

font-weight:800;

color:white;

backdrop-filter:blur(10px);

}


/* REMOVE GLOBAL WHITE */

.hero-details{

}


/* KEEP NAME + DESIGNATION WHITE */

.employee-name{

font-size:64px;

font-weight:800;

line-height:1;

margin-bottom:18px;

color:white;

}


.designation{

font-size:28px;

opacity:.95;

margin-bottom:24px;

color:white;

}



/* STATUS */

.status{

display:inline-flex;

align-items:center;

gap:10px;

padding:14px 24px;

border-radius:999px;

font-size:18px;

font-weight:700;

}



/* ACTIVE */

.status.active{

background:
rgba(43,209,109,.18);

color:
#4DFF8A;

}


.status.active .dot{

background:
#4DFF8A;

}



/* INACTIVE */

.status.inactive{

background:
rgba(255,94,94,.18);

color:
#FF6B6B;

}


.status.inactive .dot{

background:
#FF5E5E;

}



/* ON LEAVE */

.status.leave{

background:
rgba(255,180,0,.18);

color:
#FFC247;

}


.status.leave .dot{

background:
#FFC247;

}



/* FORCE STATUS TEXT COLOR */

.status,
.status *{

color:
inherit !important;

}



/* DOT */

.dot{

width:12px;

height:12px;

border-radius:50%;

flex-shrink:0;

}



/* RESPONSIVE */

@media(max-width:900px){

.employee-hero{

padding:40px;

}

.hero-content{

flex-direction:column;

text-align:center;

}

.employee-name{

font-size:44px;

}

.designation{

font-size:22px;

}

.avatar{

width:120px;

height:120px;

font-size:52px;

}

}

sp_widget.script:
(function() {

var sysId =
$sp.getParameter(
'sys_id'
);

if(!sysId)
return;

var gr =
new GlideRecord(
'x_1902481_employ_0_employee'
);

if(gr.get(sysId)){

data.name=
gr.first_name.toString();

data.designation=

gr.designation?gr.designation.getDisplayValue()

:

'';

data.status=

gr.getValue(
'status'
);

data.status_label=

gr.getDisplayValue(
'status'
);

data.initial=

data.name
.charAt(0);

}

})();
